   "tests": "import (
	"math/rand"
	"testing"
)

// bruteLCA climbs one step at a time using the parent array the test built.
func bruteLCA(parent, depth []int, u, v int) int {
	for depth[u] > depth[v] {
		u = parent[u]
	}
	for depth[v] > depth[u] {
		v = parent[v]
	}
	for u != v {
		u, v = parent[u], parent[v]
	}
	return u
}

func TestLCASmallTree(t *testing.T) {
	// 0 - 1 - 3, 1 - 4, 0 - 2 - 5
	edges := [][]int{{0, 1}, {0, 2}, {1, 3}, {1, 4}, {2, 5}}
	l := NewLCA(6, edges)
	cases := []struct {
		u, v, want int
	}{
		{3, 4, 1},
		{3, 5, 0},
		{4, 1, 1},
		{5, 2, 2},
		{3, 3, 3},
		{0, 5, 0},
	}
	for _, c := range cases {
		if got := l.Query(c.u, c.v); got != c.want {
			t.Fatalf("Query(%d, %d) = %d, want %d", c.u, c.v, got, c.want)
		}
	}
}

func TestLCAMatchesBruteForceOnRandomTrees(t *testing.T) {
	rng := rand.New(rand.NewSource(11))
	for trial := 0; trial < 20; trial++ {
		const n = 60
		parent := make([]int, n)
		depth := make([]int, n)
		parent[0] = -1
		edges := make([][]int, 0, n-1)
		for v := 1; v < n; v++ {
			p := rng.Intn(v)
			parent[v] = p
			depth[v] = depth[p] + 1
			edges = append(edges, []int{p, v})
		}
		rng.Shuffle(len(edges), func(i, j int) { edges[i], edges[j] = edges[j], edges[i] })
		l := NewLCA(n, edges)
		for q := 0; q < 200; q++ {
			u, v := rng.Intn(n), rng.Intn(n)
			if got, want := l.Query(u, v), bruteLCA(parent, depth, u, v); got != want {
				t.Fatalf("trial %d: Query(%d, %d) = %d, want %d", trial, u, v, got, want)
			}
		}
	}
}

// TestLCAOnDeepPathIsFast uses a path, where the answer is min(u, v), so a
// query that walks up one edge at a time costs O(n) and never finishes.
func TestLCAOnDeepPathIsFast(t *testing.T) {
	const n = 200000
	edges := make([][]int, 0, n-1)
	for v := 1; v < n; v++ {
		edges = append(edges, []int{v - 1, v})
	}
	l := NewLCA(n, edges)
	for q := 0; q < 400000; q++ {
		u := n - 1 - (q % 1000)
		v := n/2 + (q % 977)
		want := v
		if u < v {
			want = u
		}
		if got := l.Query(u, v); got != want {
			t.Fatalf("Query(%d, %d) = %d, want %d", u, v, got, want)
		}
	}
}"
  },
  "answer": "type LCA struct {
	up    [][]int
	depth []int
	logn  uint
}

// NewLCA roots the tree at 0 and prepares it for queries.
func NewLCA(n int, edges [][]int) *LCA {
	head := make([]int, n)
	for i := range head {
		head[i] = -1
	}
	next := make([]int, 2*len(edges))
	to := make([]int, 2*len(edges))
	add := func(i, u, v int) {
		to[i] = v
		next[i] = head[u]
		head[u] = i
	}
	for i, e := range edges {
		add(2*i, e[0], e[1])
		add(2*i+1, e[1], e[0])
	}

	logn := uint(1)
	for 1<<logn < n {
		logn++
	}
	l := &LCA{depth: make([]int, n), logn: logn}
	l.up = make([][]int, logn+1)
	for k := range l.up {
		l.up[k] = make([]int, n)
		for i := range l.up[k] {
			l.up[k][i] = -1
		}
	}

	order := make([]int, 0, n)
	if n > 0 {
		order = append(order, 0)
		l.up[0][0] = -1
		seen := make([]bool, n)
		seen[0] = true
		for i := 0; i < len(order); i++ {
			u := order[i]
			for e := head[u]; e != -1; e = next[e] {
				v := to[e]
				if seen[v] {
					continue
				}
				seen[v] = true
				l.depth[v] = l.depth[u] + 1
				l.up[0][v] = u
				order = append(order, v)
			}
		}
	}
	for k := uint(1); k <= logn; k++ {
		for v := 0; v < n; v++ {
			if mid := l.up[k-1][v]; mid >= 0 {
				l.up[k][v] = l.up[k-1][mid]
			}
		}
	}
	return l
}

// Query returns the lowest common ancestor of u and v.
func (l *LCA) Query(u, v int) int {
	if l.depth[u] < l.depth[v] {
		u, v = v, u
	}
	diff := l.depth[u] - l.depth[v]
	for k := uint(0); k <= l.logn; k++ {
		if diff&(1<<k) != 0 {
			u = l.up[k][u]
		}
	}
	if u == v {
		return u
	}
	for k := int(l.logn); k >= 0; k-- {
		if l.up[k][u] != l.up[k][v] {
			u, v = l.up[k][u], l.up[k][v]
		}
	}
	return l.up[0][u]
}",
  "explanation": "Two tables carry everything: depth[v] from one traversal of the tree, and up[k][v], the ancestor of v exactly 2^k edges above it, built from up[k][v] = up[k-1][up[k-1][v]]. That is O(n log n) to build. A query first lifts the deeper node by the bits of the depth difference, which lands both nodes on the same level; if they coincide, that node is the answer. Otherwise it walks k from high to low and lifts both nodes only when their 2^k ancestors differ, which keeps them strictly below the LCA the whole way, so after the loop their parent is the LCA. Building depths with a queue rather than recursion matters here: the test tree is a path 200000 deep.",
  "hints": [
   "Two preprocessed tables are enough: how deep each node is, and where you land jumping a power of two upward.",
   "Handle the depth gap first, using the binary representation of the difference.",
   "For the second half, lift both nodes only when the jump keeps them below the answer, then look one step up."
  ],
  "refs": [
   "LC 236 Lowest Common Ancestor of a Binary Tree",
   "LC 1483 Kth Ancestor of a Tree Node"
  ]
 },
