   "tests": "import (
	"sort"
	"testing"
)

// normalize sorts each component and then the components, so a solution is
// free to emit them in any order.
func normalize(comps [][]int) [][]int {
	out := make([][]int, 0, len(comps))
	for _, c := range comps {
		c = append([]int(nil), c...)
		sort.Ints(c)
		out = append(out, c)
	}
	sort.Slice(out, func(i, j int) bool { return out[i][0] < out[j][0] })
	return out
}

func equal(got, want [][]int) bool {
	if len(got) != len(want) {
		return false
	}
	for i := range got {
		if len(got[i]) != len(want[i]) {
			return false
		}
		for j := range got[i] {
			if got[i][j] != want[i][j] {
				return false
			}
		}
	}
	return true
}

func TestSCCTwoCyclesJoinedOneWay(t *testing.T) {
	// 0->1->2->0 and 3->4->3, with a single edge 2->3 that is not mutual.
	edges := [][]int{{0, 1}, {1, 2}, {2, 0}, {3, 4}, {4, 3}, {2, 3}}
	want := [][]int{{0, 1, 2}, {3, 4}}
	if got := normalize(stronglyConnectedComponents(5, edges)); !equal(got, want) {
		t.Fatalf("components = %v, want %v", got, want)
	}
}

// TestSCCIsNotWeakConnectivity is the case a union-find over the undirected
// edges gets wrong: the whole graph is one weakly connected piece.
func TestSCCIsNotWeakConnectivity(t *testing.T) {
	edges := [][]int{{0, 1}, {1, 2}, {2, 3}}
	want := [][]int{{0}, {1}, {2}, {3}}
	if got := normalize(stronglyConnectedComponents(4, edges)); !equal(got, want) {
		t.Fatalf("components = %v, want %v", got, want)
	}
}

func TestSCCIsolatedAndSelfLoopNodes(t *testing.T) {
	edges := [][]int{{1, 1}, {2, 3}, {3, 2}}
	want := [][]int{{0}, {1}, {2, 3}}
	if got := normalize(stronglyConnectedComponents(4, edges)); !equal(got, want) {
		t.Fatalf("components = %v, want %v", got, want)
	}
	if got := normalize(stronglyConnectedComponents(3, nil)); !equal(got, [][]int{{0}, {1}, {2}}) {
		t.Fatalf("no edges: components = %v, want three singletons", got)
	}
}

func TestSCCNestedCycleShareANode(t *testing.T) {
	// Two cycles through node 0 merge into one component; 4 hangs off it.
	edges := [][]int{{0, 1}, {1, 0}, {0, 2}, {2, 3}, {3, 0}, {3, 4}}
	want := [][]int{{0, 1, 2, 3}, {4}}
	if got := normalize(stronglyConnectedComponents(5, edges)); !equal(got, want) {
		t.Fatalf("components = %v, want %v", got, want)
	}
}

// TestSCCLargeChainOfCyclesIsLinear builds 40000 five-node cycles chained
// forward. Deciding mutual reachability with a search from every node is
// O(n*m) and does not finish.
func TestSCCLargeChainOfCyclesIsLinear(t *testing.T) {
	const groups = 60000
	const n = groups * 5
	edges := make([][]int, 0, n+groups)
	for g := 0; g < groups; g++ {
		base := g * 5
		for i := 0; i < 5; i++ {
			edges = append(edges, []int{base + i, base + (i+1)%5})
		}
		if g+1 < groups {
			edges = append(edges, []int{base + 2, base + 5})
		}
	}
	comps := stronglyConnectedComponents(n, edges)
	if len(comps) != groups {
		t.Fatalf("got %d components, want %d", len(comps), groups)
	}
	seen := make([]bool, groups)
	for _, c := range comps {
		if len(c) != 5 {
			t.Fatalf("component %v has %d nodes, want 5", c, len(c))
		}
		g := c[0] / 5
		for _, v := range c {
			if v/5 != g {
				t.Fatalf("component %v mixes cycle %d and cycle %d", c, g, v/5)
			}
		}
		if seen[g] {
			t.Fatalf("cycle %d reported twice", g)
		}
		seen[g] = true
	}
}"
