   "tests": "import (
	"sync"
	"sync/atomic"
	"testing"
	"time"
)

func TestParallelMapKeepsInputOrder(t *testing.T) {
	items := make([]int, 1000)
	for i := range items {
		items[i] = i
	}
	got := parallelMap(items, 8, func(v int) int { return v * v })
	if len(got) != len(items) {
		t.Fatalf("got %d results, want %d", len(got), len(items))
	}
	for i, v := range got {
		if v != i*i {
			t.Fatalf("result[%d] = %d, want %d", i, v, i*i)
		}
	}
}

func TestParallelMapEmptyAndSingle(t *testing.T) {
	if got := parallelMap(nil, 4, func(v int) int { return v }); len(got) != 0 {
		t.Fatalf("nil items: got %v, want an empty result", got)
	}
	if got := parallelMap([]int{7}, 4, func(v int) int { return v + 1 }); len(got) != 1 || got[0] != 8 {
		t.Fatalf("single item: got %v, want [8]", got)
	}
}

// TestParallelMapRunsConcurrently fails a sequential implementation: 16 items
// that each sleep 40ms take 640ms one at a time and about 80ms on 8 workers.
func TestParallelMapRunsConcurrently(t *testing.T) {
	items := make([]int, 16)
	for i := range items {
		items[i] = i
	}
	start := time.Now()
	got := parallelMap(items, 8, func(v int) int {
		time.Sleep(40 * time.Millisecond)
		return v
	})
	elapsed := time.Since(start)
	for i, v := range got {
		if v != i {
			t.Fatalf("result[%d] = %d, want %d", i, v, i)
		}
	}
	if elapsed > 300*time.Millisecond {
		t.Fatalf("took %v for 16 items of 40ms on 8 workers, that is not concurrent", elapsed)
	}
}

// TestParallelMapRespectsWorkerLimit fails an implementation that starts one
// goroutine per item, and also fails one that never reaches the limit.
func TestParallelMapRespectsWorkerLimit(t *testing.T) {
	const workers = 4
	items := make([]int, 40)
	for i := range items {
		items[i] = i
