	}
	next := make([]int, 2*len(edges))
	to := make([]int, 2*len(edges))
	add := func(i, u, v int) {
		to[i] = v
		next[i] = head[u]
		head[u] = i
	}
	for i, e := range edges {
		add(2*i, e[0], e[1])
		add(2*i+1, e[1], e[0])
	}

	logn := uint(1)
	for 1<<logn < n {
		logn++
	}
	l := &LCA{depth: make([]int, n), logn: logn}
	l.up = make([][]int, logn+1)
	for k := range l.up {
		l.up[k] = make([]int, n)
		for i := range l.up[k] {
			l.up[k][i] = -1
		}
	}

