package lcdrill

// knapsack returns the greatest total value of a subset of the items whose
// total weight is at most capacity, using each item at most once.
func knapsack(capacity int, weights, values []int) int {
	if capacity <= 0 {
		return 0
	}
	best := make([]int, capacity+1)
	for i, w := range weights {
		if w > capacity || w < 0 {
			continue
		}
		v := values[i]
		// Downward so the value written at c never reads a cell that already
		// includes item i: that is what makes it "at most once".
		for c := capacity; c >= w; c-- {
			if cand := best[c-w] + v; cand > best[c] {
				best[c] = cand
			}
		}
	}
	return best[capacity]
}
