package lcdrill

// longestPalindrome returns a longest palindromic substring of s, using
// Manacher's algorithm.
func longestPalindrome(s string) string {
	if len(s) == 0 {
		return ""
	}
	// t interleaves separators so every palindrome in t has odd length, which
	// removes the even/odd split: t = "^#a#b#a#$" style without sentinels.
	t := make([]byte, 0, 2*len(s)+1)
	t = append(t, '#')
	for i := 0; i < len(s); i++ {
		t = append(t, s[i], '#')
	}

	rad := make([]int, len(t))
	center, right := 0, 0
	for i := range t {
		if i < right {
			// The mirror already measured this position; trust it only up to
			// the edge of the current palindrome.
			if m := rad[2*center-i]; m < right-i {
				rad[i] = m
			} else {
				rad[i] = right - i
			}
		}
		for i-rad[i]-1 >= 0 && i+rad[i]+1 < len(t) && t[i-rad[i]-1] == t[i+rad[i]+1] {
			rad[i]++
		}
		if i+rad[i] > right {
			center, right = i, i+rad[i]
		}
	}

	bestLen, bestCenter := 0, 0
	for i, r := range rad {
		if r > bestLen {
			bestLen, bestCenter = r, i
		}
	}
	start := (bestCenter - bestLen) / 2
	return s[start : start+bestLen]
}
