package lcdrill

import "sort"

// heightHeap is a max-heap of live building heights paired with the x where
// each one ends, so a stale top can be dropped on sight.
type heightHeap struct {
	h     []int
	right []int
}

func (q *heightHeap) push(h, r int) {
	q.h = append(q.h, h)
	q.right = append(q.right, r)
	i := len(q.h) - 1
	for i > 0 {
		p := (i - 1) / 2
		if q.h[p] >= q.h[i] {
			break
		}
		q.swap(p, i)
		i = p
	}
}

func (q *heightHeap) pop() {
	last := len(q.h) - 1
	q.swap(0, last)
	q.h = q.h[:last]
	q.right = q.right[:last]
	i := 0
	for {
		l, r, big := 2*i+1, 2*i+2, i
		if l < last && q.h[l] > q.h[big] {
			big = l
		}
		if r < last && q.h[r] > q.h[big] {
			big = r
		}
		if big == i {
			return
		}
		q.swap(i, big)
		i = big
	}
}

func (q *heightHeap) swap(i, j int) {
	q.h[i], q.h[j] = q.h[j], q.h[i]
	q.right[i], q.right[j] = q.right[j], q.right[i]
}

// getSkyline returns the key points of the outline of the buildings.
func getSkyline(buildings [][]int) [][]int {
	if len(buildings) == 0 {
		return [][]int{}
	}
	order := make([]int, len(buildings))
	for i := range order {
		order[i] = i
	}
	sort.Slice(order, func(a, b int) bool {
		return buildings[order[a]][0] < buildings[order[b]][0]
	})
	xs := make([]int, 0, 2*len(buildings))
	for _, b := range buildings {
		xs = append(xs, b[0], b[1])
	}
	sort.Ints(xs)

	out := [][]int{}
	q := &heightHeap{}
	next, prev := 0, 0
	for i, x := range xs {
		if i > 0 && x == xs[i-1] {
			continue
		}
		// Everything starting here joins before the height is read, and
		// everything that has already ended leaves, so a building that ends
		// exactly where the next one starts produces no step.
		for next < len(order) && buildings[order[next]][0] == x {
			b := buildings[order[next]]
			q.push(b[2], b[1])
			next++
		}
		for len(q.h) > 0 && q.right[0] <= x {
			q.pop()
		}
		cur := 0
		if len(q.h) > 0 {
			cur = q.h[0]
		}
		if cur != prev {
			out = append(out, []int{x, cur})
			prev = cur
		}
	}
	return out
}
